class CancelledError extends Error {
  constructor(message = '已取消，未修改文件。') {
    super(message);
    this.name = 'CancelledError';
    this.exitCode = 2;
  }
}

class PromptSession {
  constructor(input = process.stdin, output = process.stdout) {
    this.output = output;
    this.readline = createInterface({ input, output, crlfDelay: Infinity });
    this.iterator = this.readline[Symbol.asyncIterator]();
    this.closed = false;
  }

  async question(prompt) {
    this.output.write(prompt);
    const next = await this.iterator.next();
    if (next.done) throw new CancelledError('输入已结束，未执行后续操作。');
    return String(next.value ?? '');
  }

  close() {
    if (this.closed) return;
    this.closed = true;
    this.readline.close();
  }
}

const ANSI = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  dim: '\x1b[2m',
  peach: '\x1b[38;2;230;165;123m',
  darkOnPeach: '\x1b[38;2;23;18;15m\x1b[48;2;230;165;123m',
  green: '\x1b[38;2;139;211;173m',
  muted: '\x1b[38;2;143;139;131m',
  white: '\x1b[38;2;245;241;235m',
  red: '\x1b[38;2;238;130;120m',
};

function paint(text, style, enabled) {
  return enabled ? `${style}${text}${ANSI.reset}` : text;
}

export function renderBrandHeader(options = {}) {
  const color = options.color !== false;
  return [
    paint('             /\\_/\\', ANSI.peach + ANSI.bold, color),
    paint('         ___/     \\___', ANSI.peach + ANSI.bold, color),
    paint('        /    ●   ●    \\       花 卷  H A R N E S S', ANSI.peach + ANSI.bold, color),
    paint('       (       ᴗ       )      让 Agent 真正理解这个目录', ANSI.white + ANSI.bold, color),
    paint('        \\    \\___/    /', ANSI.peach, color),
    paint('         \\___________/', ANSI.peach + ANSI.bold, color),
    paint('     ─────────────────────────────────────────────', ANSI.muted, color),
  ];
}

export function reduceSelectKey(state, key, options) {
  const count = options.length;
  const next = { index: state.index, action: null };
  if (!count) return next;
  if (key?.name === 'down' || key?.name === 'j') next.index = (state.index + 1) % count;
  else if (key?.name === 'up' || key?.name === 'k') next.index = (state.index - 1 + count) % count;
  else if (key?.name === 'return' || key?.name === 'enter') {
    next.action = 'confirm';
    next.value = options[state.index].value;
  } else if (key?.name === 'left') next.action = 'back';
  else if (key?.name === 'escape' || (key?.ctrl && key?.name === 'c')) next.action = 'cancel';
  return next;
}

export function reduceMultiSelectKey(state, key, options, minimum = 0) {
  const selected = new Set(state.selected ?? []);
  const next = { index: state.index, selected, action: null };
  if (key?.name === 'down' || key?.name === 'j') next.index = options.length ? (state.index + 1) % options.length : 0;
  else if (key?.name === 'up' || key?.name === 'k') next.index = options.length ? (state.index - 1 + options.length) % options.length : 0;
  else if (key?.name === 'space' && options.length) {
    const value = options[state.index].value;
    if (selected.has(value)) selected.delete(value);
    else selected.add(value);
  } else if (key?.name === 'return' || key?.name === 'enter') {
    if (selected.size < minimum) next.action = 'invalid';
    else {
      next.action = 'confirm';
      next.values = options.filter(option => selected.has(option.value)).map(option => option.value);
    }
  } else if (key?.name === 'left') next.action = 'back';
  else if (key?.name === 'escape' || (key?.ctrl && key?.name === 'c')) next.action = 'cancel';
  return next;
}

export function renderQuestionFrame(frame, options = {}) {
  const color = options.color !== false;
  const selected = frame.selected instanceof Set ? frame.selected : new Set(frame.selected ?? []);
  const lines = [
    ...renderBrandHeader({ color }),
    paint(`● 初始化 · ${frame.step} / ${frame.total}`, ANSI.muted, color),
    '',
    paint(frame.title, ANSI.white + ANSI.bold, color),
    paint(`为什么要问：${frame.why}`, ANSI.muted, color),
    '',
  ];
  if (Array.isArray(frame.summary) && frame.summary.length) {
    for (const item of frame.summary) {
      lines.push(paint(`  ${item}`, ANSI.white, color));
    }
    lines.push('');
  }
  if (frame.emptyMessage) {
    lines.push(paint(`✓ ${frame.emptyMessage}`, ANSI.green, color), '');
  }
  for (let optionIndex = 0; optionIndex < (frame.options ?? []).length; optionIndex += 1) {
    const option = frame.options[optionIndex];
    const active = optionIndex === frame.index;
    const prefix = active ? '❯' : ' ';
    const selection = frame.multi ? (selected.has(option.value) ? '✓' : '□') : option.symbol;
    const label = `${prefix} ${selection || '•'} ${option.label}`;
    lines.push(active ? paint(` ${label} `, ANSI.darkOnPeach + ANSI.bold, color) : paint(label, ANSI.white, color));
    lines.push(paint(`    ${option.description}`, ANSI.muted, color));
  }
  if (frame.multi) {
    const selectedLabels = (frame.options ?? [])
      .filter(option => selected.has(option.value))
      .map(option => option.label);
    lines.push('', paint(`已勾选 ${selectedLabels.length} 项：${selectedLabels.join('、') || '尚未勾选'}`, selectedLabels.length ? ANSI.green : ANSI.muted, color));
    lines.push(paint('提示：桃色高亮只是光标，只有 ✓ 才表示已选择。', ANSI.muted, color));
  }
  if (frame.error) lines.push('', paint(frame.error, ANSI.red, color));
  const hint = frame.multi
    ? '↑↓ 选择   Space 勾选   Enter 确认   ← 返回   Esc 取消'
    : '↑↓ 选择   Enter 确认   ← 返回   Esc 取消';
  lines.push('', paint(hint, ANSI.muted, color));
  return `${lines.join('\n')}\n`;
}

class FocusedTerminalUI {
  constructor(input = process.stdin, output = process.stdout, promptSession = null) {
    this.input = input;
    this.output = output;
    this.promptSession = promptSession;
    this.color = Boolean(output.isTTY) && !process.env.NO_COLOR;
    this.keypressReady = false;
  }

  clear() {
    if (this.output.isTTY) this.output.write('\x1b[2J\x1b[H');
    else this.output.write('\n');
  }

  async readKey() {
    if (!this.input.isTTY || typeof this.input.setRawMode !== 'function') {
      throw new Error('当前终端不支持方向键交互；请使用 --answers 进行自动化初始化。');
    }
    if (!this.keypressReady) {
      emitKeypressEvents(this.input);
      this.keypressReady = true;
    }
    const wasRaw = Boolean(this.input.isRaw);
    this.input.setRawMode(true);
    this.input.resume();
    try {
      return await new Promise(resolve => {
        this.input.once('keypress', (_text, key) => resolve(key ?? {}));
      });
    } finally {
      this.input.setRawMode(wasRaw);
      if (!wasRaw) this.input.pause();
    }
  }

  async select(stage, step, total) {
    const defaultIndex = Math.max(0, stage.options.findIndex(option => option.value === stage.defaultValue));
    let state = { index: defaultIndex, action: null };
    while (true) {
      this.clear();
      this.output.write(renderQuestionFrame({ ...stage, step, total, index: state.index, multi: false, error: state.error }, { color: this.color }));
      const next = reduceSelectKey(state, await this.readKey(), stage.options);
      if (next.action === 'confirm') return next.value;
      if (next.action === 'back') return Symbol.for('back');
      if (next.action === 'cancel') throw new CancelledError();
      state = next;
    }
  }

  async multiSelect(stage, step, total) {
    let state = {
      index: 0,
      selected: new Set(stage.defaultValues ?? []),
      action: null,
    };
    while (true) {
      this.clear();
      this.output.write(renderQuestionFrame({ ...stage, step, total, index: state.index, selected: state.selected, multi: true, error: state.error }, { color: this.color }));
      if (!stage.options.length) {
        const key = await this.readKey();
        if (key.name === 'return' || key.name === 'enter') return [];
        if (key.name === 'left') return Symbol.for('back');
        if (key.name === 'escape' || (key.ctrl && key.name === 'c')) throw new CancelledError();
        continue;
      }
      const next = reduceMultiSelectKey(state, await this.readKey(), stage.options, stage.minimum ?? 0);
      if (next.action === 'confirm') return next.values;
      if (next.action === 'back') return Symbol.for('back');
      if (next.action === 'cancel') throw new CancelledError();
      if (next.action === 'invalid') next.error = `请至少选择 ${stage.minimum} 项。`;
      state = next;
    }
  }

  async text(stage, step, total, field = null) {
    this.clear();
    const label = field?.label ?? stage.title;
    const fallback = field?.defaultValue ?? stage.defaultValue ?? '';
    this.output.write([
      ...renderBrandHeader({ color: this.color }),
      paint(`● 初始化 · ${step} / ${total}`, ANSI.muted, this.color),
      '',
      paint(stage.title, ANSI.white + ANSI.bold, this.color),
      paint(`为什么要问：${stage.why}`, ANSI.muted, this.color),
      '',
    ].join('\n'));
    const session = this.promptSession ?? new PromptSession(this.input, this.output);
    try {
      const suffix = fallback ? ` [${fallback}]` : '';
      const answer = (await session.question(`${label}${suffix}: `)).trim();
      if (answer === ':back') return Symbol.for('back');
      if (answer === ':cancel') throw new CancelledError();
      return answer || fallback;
    } finally {
      if (!this.promptSession) session.close();
    }
  }
}

